sigs = [b"FLAG", b"success_circle", b"Congrat", b"congrat", b"flag"]

def fetch(url, tries=1):
    for _ in range(tries):
        try:
            return urllib.request.urlopen(url, timeout=6).read()
        except Exception as e:
            err = e
    return b"EXC:"+str(err).encode()

# query combos
combos = []
for w in words:
    combos.append(f"page?name={urllib.parse.quote(w)}")
for a,b in itertools.product(words[:8], words[:8]):
    combos.append(f"page?name={urllib.parse.quote(a)}&hint={urllib.parse.quote(b)}")
hits = 0
for c in combos:
    body = fetch("http://web:5000/"+c)
    for s in sigs:
        if s in body:
            print("HIT", s, c)
            hits += 1
print("done", len(combos), "requests,", hits, "hits")
